// Octopus tentacles - dark blue with white spots
const tentacleColors = ['#0a3d62', '#1a5a8a', '#2a7aa0', '#3a9cbf'];
const spotColors = ['#ffffff', '#ffffff', '#ffffff', '#ffffff'];

for(let i = 0; i < 8; i++) {
    const angle = (i / 8) * Math.PI * 2;
    const x = 200 + Math.cos(angle) * 40;
    const y = 250 + Math.sin(angle) * 25;

    ctx.fillStyle = tentacleColors[i % 4];
    ctx.beginPath();
    ctx.ellipse(x, y, 8, 15, angle, 0, Math.PI * 2);
    ctx.fill();

    // Tentacle spots
    ctx.fillStyle = spotColors[i % 4];
    for(let j = 0; j < 5; j++) {
        const spotX = x + Math.cos(angle) * (10 + j * 3);
        const spotY = y + Math.sin(angle) * (10 + j * 3);
        ctx.fillRect(spotX - 2, spotY - 2, 4, 4);
    }
}

