// Draw a kaleidoscope pattern
const centerX = W / 2;
const centerY = H / 2;
const maxRadius = Math.min(W, H) / 2 - 20;

// Draw concentric circles with different colors
const colors = [
  '#ff6b6b', // pink
  '#4ecdc4', // teal
  '#45b7d1', // blue
  '#96ceb4', // green
  '#feca57', // yellow
  '#ff9ff3'  // purple
];

// Draw multiple layers of circles
for (let i = 0; i < 6; i++) {
  const radius = maxRadius - i * 20;
  const angleStep = Math.PI / 6;

  // Draw multiple segments around the center
  for (let angle = 0; angle < Math.PI * 2; angle += angleStep) {
    const x = centerX + Math.cos(angle) * radius;
    const y = centerY + Math.sin(angle) * radius;

    // Create a gradient effect within each segment
    const gradient = ctx.createRadialGradient(
      x, y, 0,
      x, y, radius
    );

    gradient.addColorStop(0, colors[i]);
    gradient.addColorStop(1, colors[(i + 1) % 6]);

    ctx.beginPath();
    ctx.arc(x, y, radius, 0, Math.PI * 2);
    ctx.fillStyle = gradient;
    ctx.fill();
  }
}

// Draw some lines to create a more complex pattern
ctx.strokeStyle = '#ffffff';
ctx.lineWidth = 1;
for (let i = 0; i < 12; i++) {
  const angle1 = (i * Math.PI / 6) - Math.PI / 12;
  const angle2 = ((i + 1) * Math.PI / 6) - Math.PI / 12;

  const x1 = centerX + Math.cos(angle1) * maxRadius;
  const y1 = centerY + Math.sin(angle1) * maxRadius;
  const x2 = centerX + Math.cos(angle2) * maxRadius;
  const y2 = centerY + Math.sin(angle2) * maxRadius;

  ctx.beginPath();
  ctx.moveTo(x1, y1);
  ctx.lineTo(x2, y2);
  ctx.stroke();
}

