  const angle = (Math.random() * Math.PI * 2);
  const radius = (maxRadius - Math.random() * 40);
  const x = centerX + Math.cos(angle) * radius;
  const y = centerY + Math.sin(angle) * radius;

  const size = 2 + Math.random() * 4;
  ctx.beginPath();
  ctx.arc(x, y, size, 0, Math.PI * 2);
  ctx.fill();
}

