    const x = 200 + Math.cos(angle) * 15;
    const y = 200 + Math.sin(angle) * 15;
    const width = 12;
    const height = 8;
    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.lineTo(x + Math.cos(angle + Math.PI/4) * width, y + Math.sin(angle + Math.PI/4) * height);
    ctx.lineTo(x + Math.cos(angle - Math.PI/4) * width, y + Math.sin(angle - Math.PI/4) * height);
    ctx.closePath();
    ctx.fill();
}

